const input = $input.first().json;
const request = input.input_data?.context_request;
if (input.workflow_code !== 'PE08' || !input.workflow_execution_id || !input.request_id || !input.organization_id || !input.conversation_id || !request || request.operation !== 'get_context_snapshot' || request.organization_id !== input.organization_id || request.conversation_id !== input.conversation_id || request.request_id !== input.request_id || (request.case_id !== null && request.case_id !== undefined && typeof request.case_id !== 'string') || input.input_data?.context_contract_version !== 'conversation-context.v2') throw new Error('INVALID_PE08_CONVERSATIONAL_ENVELOPE');
return [{json: {...input, _pe08: {contextCalls: 0, actionCalls: 0, context: null, toolCalls: []}}}];

const input = $('Validate conversational PE08 envelope').first().json;
const broker = $input.first().json;
const snapshot = broker.data || broker;
const tools = [{name:'get_context_snapshot',operation:'get_context_snapshot',parameters:{limit:'number'}},{name:'search_emails',operation:'search_emails',parameters:{query:'string',status:'string',direction:'inbound|outbound',from:'string',to:'string',limit:'number',cursor:'string'}},{name:'get_email_thread',operation:'get_email_thread',parameters:{email_id:'uuid',thread_id:'uuid',limit:'number',cursor:'string'}},{name:'search_messages',operation:'search_messages',parameters:{query:'string',sender_type:'string',role:'string',channel:'string',from:'string',to:'string',limit:'number',cursor:'string'}},{name:'list_email_drafts',operation:'list_email_drafts',parameters:{status:'string',case_id:'uuid',conversation_id:'uuid',limit:'number',cursor:'string'}},{name:'get_case_context',operation:'get_case_context',parameters:{case_id:'uuid',limit:'number'}},{name:'list_case_delegations',operation:'list_case_delegations',parameters:{case_id:'uuid',status:'string',limit:'number',cursor:'string'}},{name:'list_case_followups',operation:'list_case_followups',parameters:{case_id:'uuid',status:'string',limit:'number',cursor:'string'}},{name:'get_related_activity',operation:'get_related_activity',parameters:{case_id:'uuid',conversation_id:'uuid',activity_type:'string',from:'string',to:'string',limit:'number',cursor:'string'}}];
return [{json:{...input,_pe08:{...input._pe08,contextCalls:1,context:snapshot,tools,toolCalls:[]}}}];

const original = $('Normalize context and expose bounded tool definitions').first().json;
const model = $input.first().json;
const result = model.data || model;
const requestedToolCalls = Array.isArray(result.tool_calls) ? result.tool_calls : [];
if (requestedToolCalls.length > 5) throw new Error('PE08_CONTEXT_CALL_LIMIT_EXCEEDED');
const allowed = new Set(['get_context_snapshot','search_emails','get_email_thread','search_messages','list_email_drafts','get_case_context','list_case_delegations','list_case_followups','get_related_activity']);
for (const call of requestedToolCalls) { if (!call || !allowed.has(call.operation) || !call.parameters || typeof call.parameters !== 'object' || Array.isArray(call.parameters)) throw new Error('UNKNOWN_CONTEXT_OPERATION'); }
// This executable path intentionally performs one deterministic bounded call; max 5 is validation-only until a loop node is introduced.
const toolCalls = requestedToolCalls.slice(0,1);
return [{json:{...original,_pe08:{...original._pe08,model:result,toolCalls,toolCallsRequested:requestedToolCalls.length,toolCallsExecuted:toolCalls.length}}}];

const input = $('Validate bounded tool calls (max 5)').first().json;
const toolResult = $input.first().json;
const model = input._pe08.model || {};
const actionRequests = Array.isArray(model.action_requests) ? model.action_requests : [];
const workflowByAction = {approve_email:'PE07',reject_approval:'PE07',delegate_case:'PE04',send_email:'PE07',create_email_draft:'PE03',schedule_follow_up:'PE06',resolve_case:'PE12',verify_case:'PE12',close_case:'PE12'};
if (actionRequests.length > 3) throw new Error('PE08_ACTION_REQUEST_LIMIT_EXCEEDED');
for (const action of actionRequests) { if (!action || !workflowByAction[action.action_type] || typeof action.idempotency_key !== 'string' || !action.input_data || typeof action.input_data !== 'object' || Array.isArray(action.input_data)) throw new Error('MALFORMED_ACTION_REQUEST'); }
const workflowCalls = actionRequests.map((action, index) => ({workflow_code:workflowByAction[action.action_type],input_data:{...action.input_data,action_type:action.action_type,idempotency_key:action.idempotency_key},tool_call_id:action.tool_call_id || `${input.request_id}:action:${index + 1}`,action_type:action.action_type}));
return [{json:{...input,_pe08:{...input._pe08,toolResult,actionRequests,workflowCalls}}}];

const input = $('Validate structured action_requests (max 3)').first().json;
const bridge = $input.first().json;
const model = input._pe08.model || {};
const response = typeof model.response === 'string' ? model.response : (typeof model.content === 'string' ? model.content : '');
const coverage = model.coverage || input._pe08.context?.coverage;
if (!response || !coverage) throw new Error('INVALID_PE08_RESULT');
return [{json:{...input,output_data:{response,coverage,context_refs:model.context_refs || [],action_requests:input._pe08.actionRequests || [],workflow_calls:input._pe08.workflowCalls || [],context_calls_requested:input._pe08.toolCallsRequested || 0,context_calls_executed:input._pe08.toolCallsExecuted || 0,external_effects:bridge.external_effects || 0,network_access:bridge.network_access || false}}}];
